{
  "name": "@aexol/pi-wizard",
  "version": "0.6.0",
  "description": "Independent Pi package that exposes backend-backed Wizard tools and prompt context.",
  "type": "module",
  "private": false,
  "main": "./dist/extensions/index.js",
  "types": "./dist/extensions/index.d.ts",
  "exports": {
    ".": {
      "default": "./dist/extensions/index.js",
      "types": "./dist/extensions/index.d.ts"
    }
  },
  "files": [
    "dist",
    "README.md"
  ],
  "scripts": {
    "build": "node -e \"require('node:fs').rmSync('dist',{recursive:true,force:true})\" && tsc -p tsconfig.json",
    "release:check": "npm run typecheck && npm run build && npm pack --dry-run",
    "typecheck": "tsc --noEmit -p tsconfig.json"
  },
  "keywords": [
    "aexol",
    "pi",
    "pi-package",
    "opencode",
    "wizard",
    "skills"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://gitlab.com/aexol/open-source/opencode-wizard.git",
    "directory": "plugins/pi-wizard"
  },
  "pi": {
    "extensions": [
      "./dist/extensions"
    ],
    "skills": [],
    "prompts": [],
    "themes": []
  },
  "peerDependencies": {
    "@mariozechner/pi-coding-agent": "*"
  },
  "devDependencies": {
    "@mariozechner/pi-coding-agent": "0.70.2",
    "@types/node": "^22.12.0",
    "typescript": "^5.9.2"
  },
  "engines": {
    "node": "^20.19.0 || >=22.12.0"
  }
}
